head.b:skin:
:root{
  --bg:#FFFBF1; --surface:#FFFDF7; --ink:#211A12; --muted:#6F5F4B; --faint:#9A8A74;
  --accent:#B45309; --accent-deep:#7C2D12; --accent-soft:#FDEBC8; --line:#E9DCC3; --line-strong:#D8C69E;
  --quote:#B45309; --btn-ink:#FFF8EA; --shadow:0 10px 30px rgba(124,45,18,.10);
}
html[data-theme="sepia"]{
  --bg:#F4E7C9; --surface:#F9EFDA; --ink:#3A2A16; --muted:#6E5636; --faint:#9C8460;
  --accent:#9A3412; --accent-deep:#7C2D12; --accent-soft:#EDD9A8; --line:#DECB9C; --line-strong:#C9AE77;
  --quote:#9A3412; --shadow:0 10px 30px rgba(90,55,10,.14);
}
html[data-theme="dark"]{
  --bg:#16110B; --surface:#1E1811; --ink:#EFE4D0; --muted:#B8A88F; --faint:#8A7B63;
  --accent:#F2A93B; --accent-deep:#F2A93B; --accent-soft:#33250F; --line:#38301F; --line-strong:#55482C;
  --quote:#F2A93B; --btn-ink:#1E1503; --shadow:0 10px 30px rgba(0,0,0,.4);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--ink);font-family:"Hind Siliguri",system-ui,sans-serif;transition:background .3s,color .3s}
.serif{font-family:"Noto Serif Bengali",Georgia,serif}
a{color:var(--accent-deep)}
button,input,select{font:inherit}
button,[role="button"]{min-height:44px}
#progress{position:fixed;top:0;left:0;height:4px;width:0%;background:var(--accent);z-index:60;transition:width .08s linear}
.wrap{max-width:1120px;margin:0 auto;padding:0 20px}
.reading{max-width:720px;margin:0 auto}

/* top bar */
.topbar{position:sticky;top:0;z-index:50;background:var(--bg);border-bottom:1px solid var(--line)}
.topbar-in{display:flex;align-items:center;gap:12px;padding:10px 0;flex-wrap:wrap}
.brand-mini{font-family:"Noto Serif Bengali",serif;font-weight:900;font-size:20px;color:var(--ink);text-decoration:none;margin-right:auto}
.brand-mini span{color:var(--accent)}
.top-links{display:flex;gap:4px;flex-wrap:wrap}
.top-links a{color:var(--muted);text-decoration:none;padding:10px 10px;font-size:15px;border-radius:8px}
.top-links a:hover{color:var(--ink);background:var(--accent-soft)}
.mode-group{display:flex;border:1px solid var(--line-strong);border-radius:999px;overflow:hidden}
.mode-group button{border:0;background:transparent;color:var(--muted);padding:8px 14px;cursor:pointer;font-size:14px;font-weight:600}
.mode-group button[aria-pressed="true"]{background:var(--accent);color:var(--btn-ink)}

/* masthead */
.masthead{text-align:center;padding:52px 0 8px}
.mast-kicker{letter-spacing:.22em;font-size:12px;font-weight:700;color:var(--accent);text-transform:uppercase}
.masthead h1{font-family:"Noto Serif Bengali",serif;font-weight:900;font-size:clamp(44px,9vw,84px);line-height:1.08;margin:14px 0 6px}
.masthead h1 .flame{color:var(--accent)}
.mast-latin{font-size:15px;letter-spacing:.34em;color:var(--faint);text-transform:uppercase}
.mast-tag{font-family:"Noto Serif Bengali",serif;font-size:clamp(18px,3.4vw,23px);color:var(--muted);max-width:620px;margin:20px auto 0;line-height:1.7}
.hero-img{margin:34px auto 0;max-width:980px;border-radius:6px;overflow:hidden;box-shadow:var(--shadow)}
.hero-img img{width:100%;height:auto;display:block;aspect-ratio:16/9;object-fit:cover}
.hero-cap{text-align:center;color:var(--faint);font-size:14px;margin-top:10px}

/* toolbar */
.toolbar{margin:40px auto 0;max-width:820px;display:flex;flex-direction:column;gap:16px}
.search-row{display:flex;gap:10px;flex-wrap:wrap}
.search-box{flex:1;min-width:220px;display:flex;align-items:center;gap:8px;background:var(--surface);border:1px solid var(--line-strong);border-radius:999px;padding:4px 6px 4px 18px}
.search-box svg{flex:none}
.search-box input{flex:1;border:0;background:transparent;color:var(--ink);font-size:17px;padding:10px 0;outline:none;min-width:0}
.surprise{border:0;background:var(--accent);color:var(--btn-ink);font-weight:700;padding:10px 22px;border-radius:999px;cursor:pointer;font-size:16px;display:inline-flex;align-items:center;gap:8px}
.surprise:hover{background:var(--accent-deep);color:#FFF8EA}
.subjects{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}
.subjects button{border:1px solid var(--line-strong);background:var(--surface);color:var(--muted);border-radius:999px;padding:9px 18px;cursor:pointer;font-weight:600;font-size:15px}
.subjects button[aria-pressed="true"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}
.result-note{text-align:center;color:var(--faint);font-size:15px;min-height:22px}

/* sections */
section.block{padding:56px 0 8px}
.sec-head{display:flex;align-items:baseline;gap:16px;border-bottom:2px solid var(--ink);padding-bottom:10px;margin-bottom:28px;flex-wrap:wrap}
.sec-head h2{font-family:"Noto Serif Bengali",serif;font-size:clamp(26px,5vw,36px);margin:0;font-weight:900}
.sec-head p{margin:0;color:var(--muted);font-size:16px}

/* start here shelf */
.shelf{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.shelf-card{background:var(--surface);border:1px solid var(--line);border-top:4px solid var(--accent);padding:22px;text-align:left;cursor:pointer;border-radius:4px;color:var(--ink)}
.shelf-card:hover{box-shadow:var(--shadow)}
.shelf-card .num{font-family:"Noto Serif Bengali",serif;font-size:30px;color:var(--accent);font-weight:900}
.shelf-card h3{font-family:"Noto Serif Bengali",serif;font-size:21px;line-height:1.45;margin:10px 0 8px}
.shelf-card p{color:var(--muted);margin:0;line-height:1.6;font-size:15.5px}

/* featured */
.featured{background:var(--surface);border:1px solid var(--line);padding:clamp(24px,5vw,52px);border-radius:4px;box-shadow:var(--shadow)}
.kicker{font-size:13px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}
.featured h3{font-family:"Noto Serif Bengali",serif;font-weight:900;font-size:clamp(34px,6.5vw,54px);line-height:1.25;margin:14px 0 12px}
.meta{color:var(--faint);font-size:15px;display:flex;gap:14px;flex-wrap:wrap}
.deck{font-family:"Noto Serif Bengali",serif;font-size:clamp(18px,3vw,21px);line-height:1.85;color:var(--muted);margin:18px 0 0}
.read-btn{margin-top:24px;border:0;background:var(--ink);color:var(--bg);padding:12px 26px;border-radius:999px;font-weight:700;cursor:pointer;font-size:16px}
.read-btn:hover{background:var(--accent);color:var(--btn-ink)}

/* feed: full posts in one column, Marginalian style */
.feed{max-width:720px;margin:0 auto}
/* feed: dropdown list, one row per post; full text lives in the reader */
.post-acc{border:1px solid var(--line);border-radius:8px;background:var(--surface);margin:0 0 12px;overflow:hidden}
.post-acc summary{list-style:none;cursor:pointer;padding:18px 20px;display:flex;gap:12px;align-items:baseline;flex-wrap:wrap}
.post-acc summary::-webkit-details-marker{display:none}
.post-acc .acc-chev{color:var(--accent);font-size:16px;transition:transform .2s;flex:none}
.post-acc[open] .acc-chev{transform:rotate(180deg)}
.post-acc .acc-title{font-family:"Noto Serif Bengali",serif;font-weight:700;font-size:21px;line-height:1.45;color:var(--ink);flex:1;min-width:200px}
.post-acc .acc-meta{color:var(--faint);font-size:14px}
.post-acc .acc-panel{border-top:1px solid var(--line);padding:18px 20px 20px}
.post-acc .acc-panel .deck{margin:0 0 16px;font-size:18px}
.post-acc .read-btn{margin-top:0}
.post{padding:44px 0;border-bottom:1px solid var(--line)}
.post:first-child{padding-top:8px}
.post h3{font-family:"Noto Serif Bengali",serif;font-weight:900;font-size:clamp(27px,5.4vw,38px);line-height:1.35;margin:12px 0 10px}
.post h3 button{background:none;border:0;padding:0;text-align:left;font:inherit;color:var(--ink);cursor:pointer;min-height:0}
.post h3 button:hover{color:var(--accent-deep)}
.post .body{font-family:"Noto Serif Bengali",serif;font-size:19px;line-height:1.9;color:var(--ink)}
.post .body p{margin:0 0 16px}
.post-foot{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:6px}
.link-btn{background:none;border:0;color:var(--accent-deep);font-weight:700;cursor:pointer;padding:10px 4px;font-size:16px;text-decoration:underline;text-underline-offset:4px}
.cat-chip{border:1px solid var(--line-strong);color:var(--muted);background:var(--surface);border-radius:999px;padding:8px 14px;cursor:pointer;font-size:14px;font-weight:600}
.empty{display:none;text-align:center;color:var(--muted);padding:40px 0;font-family:"Noto Serif Bengali",serif;font-size:19px}

/* archive */
.archive-list{list-style:none;margin:0;padding:0}
.archive-list li{display:flex;gap:18px;align-items:baseline;padding:16px 0;border-bottom:1px solid var(--line);flex-wrap:wrap}
.archive-list .d{color:var(--faint);font-size:15px;min-width:118px}
.archive-list button{background:none;border:0;padding:6px 0;font-family:"Noto Serif Bengali",serif;font-size:19px;font-weight:700;color:var(--ink);cursor:pointer;text-align:left;min-height:0}
.archive-list button:hover{color:var(--accent-deep)}
.archive-list .c{margin-left:auto;color:var(--accent);font-size:14px;font-weight:700}

/* about + newsletter */
.about-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:22px}
.about-card{background:var(--surface);border:1px solid var(--line);padding:28px;border-radius:4px}
.about-card h3{font-family:"Noto Serif Bengali",serif;font-size:24px;margin:0 0 12px}
.about-card p{color:var(--muted);line-height:1.8;margin:0 0 12px;font-size:16.5px}
.news-box{background:var(--accent-soft);border:1px solid var(--line-strong);padding:28px;border-radius:4px}
.news-box h3{font-family:"Noto Serif Bengali",serif;font-size:24px;margin:0 0 10px;color:var(--ink)}
.news-box p{color:var(--muted);line-height:1.7;margin:0 0 16px}
.news-form{display:flex;gap:8px;flex-wrap:wrap}
.news-form input{flex:1;min-width:180px;border:1px solid var(--line-strong);background:var(--surface);color:var(--ink);border-radius:999px;padding:12px 18px;font-size:16px}
.news-form button{border:0;background:var(--accent);color:var(--btn-ink);font-weight:700;border-radius:999px;padding:12px 22px;cursor:pointer}
.news-done{display:none;color:var(--accent-deep);font-weight:700;margin-top:12px}

/* reader */
#reader{display:none;padding:36px 0 10px}
.back-btn{background:none;border:1px solid var(--line-strong);color:var(--ink);border-radius:999px;padding:10px 20px;cursor:pointer;font-weight:600}
.reader-head{text-align:center;padding:34px 0 8px}
.reader-head h2{font-family:"Noto Serif Bengali",serif;font-weight:900;font-size:clamp(32px,6.8vw,50px);line-height:1.3;margin:14px 0 14px}
.reader-head .meta{justify-content:center}
.standfirst{font-family:"Noto Serif Bengali",serif;font-size:clamp(19px,3.4vw,22px);line-height:1.85;color:var(--muted);text-align:center;max-width:640px;margin:20px auto 0}
.reader-body{font-family:"Noto Serif Bengali",serif;font-size:19.5px;line-height:1.95}
.reader-body p{margin:0 0 22px}
.pull{font-family:"Noto Serif Bengali",serif;font-size:clamp(23px,4.6vw,30px);line-height:1.6;font-weight:700;text-align:center;margin:38px auto;max-width:600px;color:var(--ink)}
.pull::before{content:"“";display:block;font-size:64px;line-height:.6;color:var(--quote);margin-bottom:14px}
.couple{border-top:2px solid var(--ink);margin-top:48px;padding-top:22px}
.couple h3{font-family:"Noto Serif Bengali",serif;font-size:22px;margin:0 0 6px}
.couple p{color:var(--muted);margin:0 0 14px}
.couple ul{list-style:none;margin:0;padding:0}
.couple li{padding:12px 0;border-bottom:1px solid var(--line)}
.couple button{background:none;border:0;padding:6px 0;font-family:"Noto Serif Bengali",serif;font-size:19px;font-weight:700;color:var(--accent-deep);cursor:pointer;text-align:left;min-height:0}
.reader-news{margin-top:36px}
.orig-link{display:inline-block;margin-top:22px;font-weight:700}

footer{margin-top:70px;border-top:1px solid var(--line);padding:34px 0 54px;color:var(--muted)}
footer .cols{display:flex;gap:28px;flex-wrap:wrap;justify-content:space-between}
footer a{color:var(--muted)}
footer .small{font-size:14px;color:var(--faint);max-width:640px;line-height:1.7}

@media (max-width:760px){
  .brand-mini{font-size:17px}
  .mode-group button{padding:8px 10px;font-size:13px}
  .topbar-in{gap:8px;justify-content:space-between}
  .shelf{grid-template-columns:1fr}
  .about-grid{grid-template-columns:1fr}
  .masthead{padding-top:36px}
  .archive-list .c{margin-left:0}
  .top-links{display:none}
}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}

/* ---- Blogger adaptations ---- */
#navbar-iframe,.navbar{display:none!important}
.pull:empty{display:none}
.body img,.reader-body img{max-width:100%;height:auto}
.body iframe,.reader-body iframe{max-width:100%}
.body a,.reader-body a{word-break:break-word}
.noscript-posts{max-width:720px;margin:20px auto;padding:0 20px;font-family:"Noto Serif Bengali",serif;line-height:1.9}

body.script:
//
var HOME_TITLE = "শিরোনামহীন দহন · Shironamhin Dohon";
var CATS = {
  all: {bn:"সব বিষয়", en:"All"},
  politics: {bn:"বাংলাদেশের রাজনীতি", en:"Bangladesh Politics"},
  international: {bn:"আন্তর্জাতিক", en:"International News"},
  economy: {bn:"অর্থনীতি", en:"Economy"},
  stories: {bn:"ব্যক্তিগত গল্প", en:"Personal Stories"}
};
/* Blogger label -> category. Add more spellings here if your labels differ. */
var CAT_ALIASES = {
  politics: ["politics","bangladesh politics","রাজনীতি","বাংলাদেশের রাজনীতি"],
  international: ["international","international news","আন্তর্জাতিক","world"],
  economy: ["economy","economics","অর্থনীতি"],
  stories: ["stories","story","personal stories","personal","গল্প","ব্যক্তিগত গল্প"]
};
/* Posts with one of these labels appear in "এখান থেকে শুরু করুন" (max 3). */
var START_ALIASES = ["start here","start-here","starthere","এখান থেকে শুরু","এখান থেকে শুরু করুন"];
var BN_MONTHS = ["জানুয়ারি","ফেব্রুয়ারি","মার্চ","এপ্রিল","মে","জুন","জুলাই","আগস্ট","সেপ্টেম্বর","অক্টোবর","নভেম্বর","ডিসেম্বর"];
var EN_MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
var POSTS = [];
var START_HERE = [];
var state = {cat:"stories", q:""};
/* Our own story writing: personal stories plus unlabelled essays. News (politics, international, economy) shows only under its menu button. */
function isStory(p){ return p.cat === "stories" || p.cat === "other"; }

function el(id){return document.getElementById(id);}
function byId(id){for(var i=0;i<POSTS.length;i++){if(POSTS[i].id===id)return POSTS[i];}return null;}
function catLabel(p){ var c = CATS[p.cat] || CATS.all; return c.en + " · " + c.bn; }
function esc(s){ return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function bnDigits(n){ return String(n).replace(/\d/g,function(d){ return "০১২৩৪৫৬৭৮৯".charAt(+d); }); }
function fmtDate(iso){
  var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso || ""); if(!m) return {en:"", bn:""};
  var y = m[1], mo = +m[2]-1, d = +m[3];
  return {en: d + " " + EN_MONTHS[mo] + " " + y, bn: bnDigits(d) + " " + BN_MONTHS[mo] + " " + bnDigits(y)};
}
function pathOf(u){
  var a = document.createElement("a"); a.href = u; var p = a.pathname;
  if(p.charAt(0) !== "/") p = "/" + p;
  return p.replace(/\/+$/, "") || "/";
}
function postByPath(path){
  path = (path || "").replace(/\/+$/, "");
  try{ path = decodeURI(path); }catch(e){}
  for(var i=0;i<POSTS.length;i++){
    var pp = POSTS[i].path; try{ pp = decodeURI(pp); }catch(e){}
    if(pp === path) return POSTS[i];
  }
  return null;
}
function stripTags(h){ var d = document.createElement("div"); d.innerHTML = h; return (d.textContent || "").replace(/\s+/g," ").trim(); }

/* Turn Blogger's post HTML into paragraph blocks, like the original design expects. */
function toParas(html){
  var d = document.createElement("div"); d.innerHTML = html;
  var junk = d.querySelectorAll("script,style,link,meta,object,embed,form");
  for(var i=0;i<junk.length;i++) junk[i].parentNode.removeChild(junk[i]);
  var out = [], cur = "";
  function clean(h){ return h.replace(/^(?:\s|&nbsp;|<br\s*\/?>)+|(?:\s|&nbsp;|<br\s*\/?>)+$/gi, ""); }
  function flush(){
    if(cur){
      cur.split(/(?:<br\s*\/?>\s*){2,}/i).forEach(function(x){
        x = clean(x);
        if(x && (stripTags(x) || /<(img|iframe)/i.test(x))) out.push("<p>" + x + "</p>");
      });
    }
    cur = "";
  }
  Array.prototype.slice.call(d.childNodes).forEach(function(n){
    if(n.nodeType === 3){ cur += esc(n.nodeValue); return; }
    if(n.nodeType !== 1) return;
    var tag = n.tagName.toLowerCase();
    if(tag === "div" || tag === "p"){ flush(); cur = n.innerHTML; flush(); }
    else if(/^(h[1-6]|ul|ol|blockquote|figure|table|pre|hr)$/.test(tag)){ flush(); out.push(n.outerHTML); }
    else cur += n.outerHTML;
  });
  flush();
  return out;
}
function catFor(labels){
  var keys = Object.keys(CAT_ALIASES);
  for(var i=0;i<labels.length;i++){
    var lab = labels[i].toLowerCase().trim();
    for(var k=0;k<keys.length;k++){
      var al = CAT_ALIASES[keys[k]];
      for(var a=0;a<al.length;a++){ if(lab === al[a] || lab.indexOf(al[a]) !== -1) return keys[k]; }
    }
  }
  return "other";
}
function parseFeed(data){
  var entries = (data && data.feed && data.feed.entry) || [], out = [];
  entries.forEach(function(e){
    var url = "";
    (e.link || []).forEach(function(l){ if(l.rel === "alternate") url = l.href; });
    var idm = /post-(\d+)/.exec((e.id && e.id.$t) || ""); var id = idm ? idm[1] : "p" + out.length;
    var labels = (e.category || []).map(function(c){ return c.term; });
    var html = (e.content && e.content.$t) || (e.summary && e.summary.$t) || "";
    var paras = toParas(html);
    var text = stripTags(paras.join(" "));
    var deck = text;
    if(deck.length > 200){ deck = deck.slice(0,200); deck = deck.slice(0, Math.max(deck.lastIndexOf(" "), 120)) + "…"; }
    var words = text ? text.split(/\s+/).length : 0;
    var dt = fmtDate(e.published && e.published.$t);
    out.push({
      id:id, title:(e.title && e.title.$t) || "(শিরোনামহীন)", url:url, path:url ? pathOf(url) : "",
      date:dt.en, dateBn:dt.bn, labels:labels, cat:catFor(labels), mins:Math.max(1, Math.round(words/180)),
      deck:deck, bodyHtml:paras.join(""), text:text, quote:""
    });
  });
  return out;
}
function relatedIds(p){
  var rows = POSTS.filter(function(o){ return o.id !== p.id; }).map(function(o, i){
    var s = 0;
    o.labels.forEach(function(l){ if(p.labels.indexOf(l) !== -1) s += 2; });
    if(o.cat === p.cat) s += 1;
    return {id:o.id, s:s, i:i};
  });
  rows.sort(function(a,b){ return (b.s - a.s) || (a.i - b.i); });
  return rows.slice(0,3).map(function(r){ return r.id; });
}

function renderSubjects(){
  var bar = el("subjectBar"); bar.innerHTML = "";
  ["stories","politics","international","economy"].forEach(function(k){
    var b = document.createElement("button");
    b.type = "button"; b.textContent = CATS[k].bn;
    b.setAttribute("aria-pressed", state.cat===k ? "true":"false");
    b.addEventListener("click", function(){ state.cat = k; renderSubjects(); renderFeed(); });
    bar.appendChild(b);
  });
}
function matches(p){
  var okCat = state.cat==="stories" ? isStory(p) : p.cat===state.cat;
  if(!okCat) return false;
  if(!state.q) return true;
  var c = CATS[p.cat] || CATS.all;
  var hay = (p.title + " " + p.deck + " " + c.en + " " + c.bn + " " + p.labels.join(" ") + " " + p.text).toLowerCase();
  return hay.indexOf(state.q.toLowerCase()) !== -1;
}
function metaLine(p){ return p.dateBn + " · " + p.date + " · " + p.mins + " মিনিটে পড়ুন"; }

function renderFeatured(){
  var sp = POSTS.filter(isStory);
  var p = sp.length ? sp[0] : POSTS[0];
  if(!p){ el("featuredSec").style.display = "none"; return; }
  el("featuredCard").innerHTML =
    '<div class="kicker">' + catLabel(p) + '</div>' +
    '<h3 class="serif">' + esc(p.title) + '</h3>' +
    '<div class="meta"><span>' + metaLine(p) + '</span></div>' +
    '<p class="deck">' + esc(p.deck) + '</p>' +
    '<button class="read-btn" type="button" data-open="' + p.id + '">লেখাটি পড়ুন</button>';
}
function renderShelf(){
  var s = el("shelf"); s.innerHTML = "";
  if(!START_HERE.length){ el("shelfSec").style.display = "none"; return; }
  START_HERE.forEach(function(id, i){
    var p = byId(id); if(!p) return;
    var c = document.createElement("button");
    c.type = "button"; c.className = "shelf-card";
    c.innerHTML = '<div class="num">' + (i+1) + '</div><h3>' + esc(p.title) + '</h3><p>' + esc(p.deck) + '</p>';
    c.addEventListener("click", function(){ openReader(p.id); });
    s.appendChild(c);
  });
}
function renderFeed(){
  var feed = el("feed"); feed.innerHTML = "";
  var shown = 0;
  POSTS.forEach(function(p){
    if(!matches(p)) return;
    shown++;
    var art = document.createElement("details");
    art.className = "post-acc";
    art.innerHTML =
      '<summary><span class="acc-chev">\u25be</span><span class="acc-title">' + esc(p.title) + '</span>' +
      '<span class="acc-meta">' + catLabel(p) + ' \u00b7 ' + metaLine(p) + '</span></summary>' +
      '<div class="acc-panel"><p class="deck">' + esc(p.deck) + '</p>' +
      '<div class="post-foot"><button class="read-btn" type="button" data-open="' + p.id + '">লেখাটি পড়ুন</button>' +
      '<button class="cat-chip" type="button" data-cat="' + p.cat + '">' + (CATS[p.cat] || CATS.all).bn + ' এর লেখা দেখুন</button></div></div>';
    feed.appendChild(art);
  });
  el("emptyNote").style.display = (shown || !POSTS.length) ? "none" : "block";
  el("resultNote").textContent = shown ? ("মোট " + shown + "টি লেখা দেখানো হচ্ছে · আর্কাইভে মোট " + POSTS.length + "টি প্রকাশিত লেখা") : "";
  bindOpeners(feed);
}
function renderArchive(){
  var ul = el("archiveList"); ul.innerHTML = "";
  var listed = POSTS.filter(isStory);
  listed.forEach(function(p){
    var li = document.createElement("li");
    li.innerHTML = '<span class="d">' + p.date + '</span>';
    var b = document.createElement("button");
    b.type = "button"; b.textContent = p.title;
    b.addEventListener("click", function(){ openReader(p.id); });
    li.appendChild(b);
    var c = document.createElement("span"); c.className = "c"; c.textContent = (CATS[p.cat] || CATS.all).en;
    li.appendChild(c);
    ul.appendChild(li);
  });
  var since = listed.length ? listed[listed.length-1].date : "";
  el("archiveNote").textContent = "Page 1 of 1 · " + listed.length + " published posts" + (since ? " · since " + since : "");
}
function bindOpeners(root){
  var btns = root.querySelectorAll("[data-open]");
  for(var i=0;i<btns.length;i++){ (function(btn){
    btn.addEventListener("click", function(){ openReader(btn.getAttribute("data-open")); });
  })(btns[i]); }
  var chips = root.querySelectorAll("[data-cat]");
  for(var j=0;j<chips.length;j++){ (function(ch){
    ch.addEventListener("click", function(){ state.cat = ch.getAttribute("data-cat"); renderSubjects(); renderFeed(); window.scrollTo({top: el("feedSec").offsetTop - 80, behavior:"smooth"}); });
  })(chips[j]); }
}
function openReader(id, noPush){
  var p = byId(id); if(!p) return;
  el("rKicker").textContent = catLabel(p);
  el("rTitle").textContent = p.title;
  el("rMeta").innerHTML = "<span>" + metaLine(p) + "</span><span>লেখক: Mashkur Ahmed Sakib</span>";
  el("rStand").textContent = p.deck;
  el("rBody").innerHTML = p.bodyHtml;
  el("rPull").textContent = p.quote;
  if(p.url) el("origLink").href = p.url;
  var ul = el("rRelated"); ul.innerHTML = "";
  relatedIds(p).forEach(function(rid){
    var r = byId(rid); if(!r) return;
    var li = document.createElement("li");
    var b = document.createElement("button");
    b.type = "button"; b.textContent = r.title + "  ·  " + r.date;
    b.addEventListener("click", function(){ openReader(r.id); });
    li.appendChild(b); ul.appendChild(li);
  });
  el("homeView").style.display = "none";
  el("reader").style.display = "block";
  document.title = p.title + " · শিরোনামহীন দহন";
  if(!noPush && p.path && window.history && history.pushState){ try{ history.pushState(null, "", p.path); }catch(e){} }
  window.scrollTo(0,0); updateProgress();
}
function closeReader(noPush){
  el("reader").style.display = "none";
  el("homeView").style.display = "block";
  document.title = HOME_TITLE;
  if(noPush !== true && window.history && history.pushState){ try{ history.pushState(null, "", "/"); }catch(e){} }
  window.scrollTo(0,0); updateProgress();
}
function updateProgress(){
  var h = document.documentElement;
  var max = h.scrollHeight - h.clientHeight;
  var pct = max > 0 ? (h.scrollTop / max) * 100 : 0;
  el("progress").style.width = pct + "%";
}
window.addEventListener("scroll", updateProgress, {passive:true});
window.addEventListener("popstate", function(){
  var p = postByPath(location.pathname);
  if(p) openReader(p.id, true); else closeReader(true);
});

el("searchInput").addEventListener("input", function(e){ state.q = e.target.value.trim(); renderFeed(); });
el("surpriseBtn").addEventListener("click", function(){
  var pool = POSTS.filter(matches);
  if(!pool.length) pool = POSTS;
  if(!pool.length) return;
  var pick = pool[Math.floor(Math.random() * pool.length)];
  openReader(pick.id);
});
el("backBtn").addEventListener("click", function(){ closeReader(); });
el("homeLink").addEventListener("click", function(e){ e.preventDefault(); closeReader(); });

var modeBtns = document.querySelectorAll("[data-mode]");
for(var m=0;m<modeBtns.length;m++){ (function(btn){
  btn.addEventListener("click", function(){
    document.documentElement.setAttribute("data-theme", btn.getAttribute("data-mode"));
    for(var k=0;k<modeBtns.length;k++){ modeBtns[k].setAttribute("aria-pressed", modeBtns[k]===btn ? "true":"false"); }
  });
})(modeBtns[m]); }

var forms = document.querySelectorAll("[data-news]");
for(var f=0;f<forms.length;f++){ (function(form){
  form.addEventListener("submit", function(e){
    e.preventDefault();
    var box = form.parentElement.querySelector(".news-done");
    if(box) box.style.display = "block";
    form.reset();
  });
})(forms[f]); }

function finish(){
  var used = {};
  POSTS.forEach(function(p){ used[p.cat] = true; });
  if(used.other) CATS.other = {bn:"অন্যান্য", en:"Other"};
  var tagged = POSTS.filter(function(p){
    return isStory(p) && p.labels.some(function(l){ return START_ALIASES.indexOf(l.toLowerCase().trim()) !== -1; });
  }).slice(0,3);
  var storyPosts = POSTS.filter(isStory);
  var pick = tagged.length ? tagged : storyPosts.slice(0,3);
  if(!pick.length) pick = POSTS.slice(0,3);
  START_HERE = pick.map(function(p){ return p.id; });
  renderSubjects(); renderFeatured(); renderShelf(); renderFeed(); renderArchive(); bindOpeners(document);
  var cur = postByPath(location.pathname);
  if(cur) openReader(cur.id, true); else el("homeView").style.display = "block";
  updateProgress();
}
function failed(){
  el("homeView").style.display = "block";
  el("resultNote").textContent = "লেখা লোড করা যায়নি। পাতাটি রিফ্রেশ করুন।";
  renderSubjects();
}
(function load(){
  el("resultNote").textContent = "লেখা লোড হচ্ছে…";
  var x = new XMLHttpRequest();
  x.open("GET", "/feeds/posts/default?alt=json&max-results=500");
  x.onload = function(){
    try{ POSTS = parseFeed(JSON.parse(x.responseText)); }catch(err){ failed(); return; }
    finish();
  };
  x.onerror = failed;
  x.send();
})();
updateProgress();

//
